"use client";

import Link from "next/link";
import Navbar from "../../components/Home/Nevbar";
import EmployedDashboard from "../../components/employed/EmployedDashboard";
import TherapyPlayerEmployed from "../../components/employed/TherapyPlayerEmployed";

export default function EmployedPage() {
  return (
    <div className="min-h-screen bg-[#E6F7F1] font-sans">
      <Navbar />

      <main className="mx-auto p-6 md:px-10 md:py-8 grid grid-cols-1 gap-8 items-start">
        <div>
          <EmployedDashboard />
        </div>
        <div>
          <TherapyPlayerEmployed />
        </div>
        <div>
          <section className="bg-white p-6 rounded-xl shadow-lg">
            <h3 className="text-xl font-semibold text-[#064E3B] mb-2">References</h3>
            <p className="text-sm text-gray-600 mb-4">Find additional resources and references for employed professionals.</p>
            <Link href="/references" className="inline-block px-4 py-2 bg-[#10B981] text-white rounded-lg font-medium hover:bg-[#059669] transition-colors">
              View References
            </Link>
          </section>
        </div>
      </main>

      <footer className="mt-12 p-6 text-center text-[#065F46]">
        &copy; {new Date().getFullYear()} Healthcare Support. All rights reserved.
      </footer>
    </div>
  );
}
