"use client";

import { useState } from "react";
import EmployedQuestionnaire from "./EmployedQuestionnaire";
import TherapyPlayerEmployed from "./TherapyPlayerEmployed";

export default function EmployedDashboard() {
  const defaultVideoId = "lmyZMtPVodo"; // Simon Sinek — How Great Leaders Inspire Action
  const [recommendedId, setRecommendedId] = useState<string | null>(defaultVideoId);

  return (
    <div className="w-full">
      <h2 className="text-2xl font-bold text-[#064E3B]">Employed Professionals Dashboard</h2>

      <p className="text-sm text-gray-600 mt-2">
        Complete the quick 9-question stress check for employed professionals and watch recommended motivational videos from famous personalities.
      </p>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mt-6 w-full">
        <EmployedQuestionnaire onRecommend={(id) => setRecommendedId(id)} />
        <TherapyPlayerEmployed initialYouTubeId={recommendedId ?? defaultVideoId} />
      </div>
    </div>
  );
}
